package main

import "fmt"

type MyInterface interface {
    M1()
}

type T int

func (T) M1() {
    fmt.Println("T's M1")
}

func main() {
    var t T
    var i any = t

    v1, ok := i.(MyInterface)
    if !ok {
        panic("the value of i is not MyInterface")
    }
    v1.M1()
    fmt.Printf("the type of v1 is %T\n", v1)

    i = int64(13)
    v2, ok := i.(MyInterface)
    fmt.Printf("ok=%t, the type of v2 is %T, nil=%t\n", ok, v2, v2 == nil)
    // v2 = 13 // 故意取消注释会编译失败：int 不实现 MyInterface。
}

