package main

import "fmt"

type T struct { a int }

func (t T) Get() int { return t.a }
func (t *T) Set(a int) int { t.a = a; return t.a }

func Get(t T) int { return t.a }
func Set(t *T, a int) int { t.a = a; return t.a }

func main() {
    var t T
    t.Set(1)
    fmt.Println(t.Get())
    fmt.Println(T.Get(t))
    fmt.Println((*T).Set(&t, 2))
    f1 := (*T).Set
    f2 := T.Get
    fmt.Printf("%T\n", f1)
    fmt.Printf("%T\n", f2)
    f1(&t, 3)
    fmt.Println(f2(t))
}

package main

import (
    "fmt"
    "time"
)

type field struct { name string }

func (p *field) print() { fmt.Println(p.name) }

func main() {
    data1 := []*field{{"one"}, {"two"}, {"three"}}
    for _, v := range data1 {
        go v.print()
    }
    data2 := []field{{"four"}, {"five"}, {"six"}}
    for _, v := range data2 {
        go v.print()
    }
    time.Sleep(3 * time.Second)
}

for _, v := range data1 {
    go (*field).print(v)
}
for _, v := range data2 {
    go (*field).print(&v)
}

package main

import "fmt"

type field struct { name string }

func (p field) print() { fmt.Println(p.name) }

func main() {
    done := make(chan struct{}, 6)
    data1 := []*field{{"one"}, {"two"}, {"three"}}
    for _, v := range data1 {
        // 先复制值，再交给 goroutine；等价于本轮的 field.print(*v)。
        go func(p field) { p.print(); done <- struct{}{} }(*v)
    }
    data2 := []field{{"four"}, {"five"}, {"six"}}
    for _, v := range data2 {
        go func(p field) { p.print(); done <- struct{}{} }(v)
    }
    for i := 0; i < 6; i++ { <-done }
}

