package main

import (
    "errors"
    "fmt"
)

type MyError struct {
    error
}

var ErrBad = MyError{
    error: errors.New("bad things happened"),
}

func bad() bool {
    return false
}

func returnsError() error {
    var p *MyError = nil
    if bad() {
        p = &ErrBad
    }
    return p
}

func main() {
    if err := returnsError(); err != nil {
        fmt.Printf("error occur: %+v\n", err)
        return
    }
    fmt.Println("ok")
}

func returnsError() error {
    if bad() {
        return &ErrBad
    }
    return nil
}

// 这是另一种替换方案，不和上一个同名函数同时声明。
func returnsError() error {
    var p error
    if bad() {
        p = &ErrBad
    }
    return p
}

