	*MyInt
	t
	io.Reader
	s string
	n int
}

func main() {
	m := MyInt(17)
	s := S{
		MyInt: &m,
		t: t{a: 1, b: 2},
		Reader: strings.NewReader("hello, go"),
		s: "demo",
	}
	buf := make([]byte, len("hello, go"))
	n, err := s.Reader.Read(buf)
	if err != nil && err != io.EOF {
		panic(err)
	}
	fmt.Println(string(buf[:n]))
	s.MyInt.Add(5)
	fmt.Println(*s.MyInt)
}

package main

import (
