type T1 int
func (T1) T1M1() {}
func (*T1) PT1M2() {}

type T2 int
func (T2) T2M1() {}
func (*T2) PT2M2() {}

type T struct {
	T1
	*T2
}

func names(v any) []string {
	typ := reflect.TypeOf(v)
	var result []string
	for i := 0; i < typ.NumMethod(); i++ {
		result = append(result, typ.Method(i).Name)
	}
	return result
}

func main() {
	fmt.Println(names(T{}))
	fmt.Println(names(&T{}))
}

