package main

import (
	"fmt"
	"reflect"
)

type T struct{}
func (T) M1() {}
func (T) M2() {}

type S T

type Alias = T

func names(v any) []string {
	typ := reflect.TypeOf(v)
	var result []string
	for i := 0; i < typ.NumMethod(); i++ {
		result = append(result, typ.Method(i).Name)
	}
	return result
}

func main() {
	fmt.Println(names(S{}), names(&S{}))
	fmt.Println(names(Alias{}), names(&Alias{}))
	fmt.Printf("%T\n", Alias{})
	var s S
	T(s).M1()
}

type E struct{}
func (E) Promoted() {}

type Original struct { E }
func (Original) Own() {}

type Defined Original
// Defined 没有 Own，但仍能沿其嵌入字段 E 提升 Promoted。

type I interface { M1() }
type NI I
// NI 与 I 是不同的定义接口类型，具有相同的方法要求。

func TestSave(t *testing.T) {
	var buf bytes.Buffer
	data := []byte("hello, golang")
	if err := Save(&buf, data); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(buf.Bytes(), data) {
		t.Fatalf("want %q, actual %q", data, buf.Bytes())
	}
}

