package main

import (
	"fmt"
	"io"
	"strings"
)

type upper struct { r io.Reader }

func (u upper) Read(p []byte) (int, error) {
	n, err := u.r.Read(p)
	for i := 0; i < n; i++ {
		if p[i] >= 'a' && p[i] <= 'z' {
			p[i] -= 'a' - 'A'
		}
	}
	return n, err
}

func CapReader(r io.Reader) io.Reader { return upper{r: r} }

func main() {
	var r io.Reader = strings.NewReader("hello gopher")
	r = io.LimitReader(r, 8)
	r = CapReader(r)
	b, err := io.ReadAll(r)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(b))

	r = CapReader(io.LimitReader(strings.NewReader("hello, gopher!\n"), 4))
	b, err = io.ReadAll(r)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(b))
}

type SendFunc func(string)

func (f SendFunc) Send(message string) { f(message) }

func example() {
	Welcome(SendFunc(func(message string) {
		fmt.Println("记录通知：", message)
	}))
}

type Handler interface {
	ServeHTTP(ResponseWriter, *Request)
}

type HandlerFunc func(ResponseWriter, *Request)

func (f HandlerFunc) ServeHTTP(w ResponseWriter, r *Request) {
	f(w, r)
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
)

func logMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Println("log:", r.URL.Path)
		next.ServeHTTP(w, r)
	})
}

func authMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Println("auth check")
		if r.Header.Get("X-Token") == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "hello")
	})
	srv := logMW(authMW(h))
	for _, token := range []string{"", "t"} {
		req := httptest.NewRequest("GET", "/ping", nil)
		if token != "" {
			req.Header.Set("X-Token", token)
		}
		rec := httptest.NewRecorder()
		srv.ServeHTTP(rec, req)
		fmt.Println(rec.Code, rec.Body.String())
	}
}

func WelcomeUnknown(value any) bool {
	sender, ok := value.(Sender)
	if !ok {
		return false
	}
	Welcome(sender)
	return true
}

func exampleAny() {
	fmt.Println(WelcomeUnknown(Email{}))
	fmt.Println(WelcomeUnknown(SMS{}))
	fmt.Println(WelcomeUnknown(42))
}

